<?php
declare(strict_types=1);
$pageTitle='Annual Harvests';
require_once '../includes/header.php';
require_once '../includes/sidebar.php';
require_once '../church_admin/common.php';
require_once '../church_admin/install.php';
if(!isset($conn)||!($conn instanceof mysqli))die('Database connection not found.');
ce_require_admin();ce_install($conn);
$departments=ce_departments($conn);$departmentNames=[];foreach($departments as $d)$departmentNames[(int)$d['id']]=(string)$d['name'];
$zones=ce_zones($conn);
$rows=ce_query_all($conn,'SELECT * FROM church_harvests ORDER BY harvest_year DESC, harvest_date DESC, id DESC');
$rows=ce_attach_departments($conn,$rows,'church_harvest_departments','harvest_id',$departmentNames);
$target=0.0;$collected=0.0;foreach($rows as $row){$target+=(float)$row['target_amount'];$collected+=(float)$row['amount_collected'];}$overall=$target>0?min(100,($collected/$target)*100):0;
?>
