<div class="main-content"><?php include '../includes/topbar.php';?><div class="content-area"><?php ce_show_flash();?><div class="church-page-head"><div><h2><i class="fas fa-wheat-awn"></i> Annual Harvests</h2><p>Manage zone, Sunday School and general harvests for all members or selected departments.</p></div><button type="button" class="btn btn-primary" id="addBtn"><i class="fas fa-plus"></i> Add Harvest</button></div><div class="church-stats"><div class="church-stat"><div class="church-stat-icon"><i class="fas fa-list"></i></div><div><b><?=count($rows)?></b><span>Harvest Records</span></div></div><div class="church-stat"><div class="church-stat-icon"><i class="fas fa-bullseye"></i></div><div><b><?=number_format($target,0)?></b><span>Total Target</span></div></div><div class="church-stat"><div class="church-stat-icon"><i class="fas fa-coins"></i></div><div><b><?=number_format($collected,0)?></b><span>Total Collected</span></div></div><div class="church-stat"><div class="church-stat-icon"><i class="fas fa-chart-line"></i></div><div><b><?=number_format($overall,1)?>%</b><span>Overall Progress</span></div></div></div><div class="church-card"><div class="page-toolbar"><div class="page-toolbar-search"><i class="fas fa-search"></i><input type="search" id="recordSearch" class="form-control" placeholder="Search records..."></div><div class="page-toolbar-actions"><a href="index.php" class="btn btn-outline-primary page-toolbar-refresh"><i class="fas fa-rotate-right"></i> Refresh</a></div></div><div class="church-table-wrap"><table class="church-table"><thead><tr><th>Year</th><th>Harvest</th><th>Category</th><th>Audience</th><th>Progress</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):$pct=(float)$r['target_amount']>0?min(100,((float)$r['amount_collected']/(float)$r['target_amount'])*100):0;?><tr data-search="<?=ce_h(strtolower(implode(' ',[$r['harvest_year'],$r['harvest_name'],$r['harvest_category'],$r['zone_name'],$r['department_names'],$r['status']])))?>"><td><b><?=ce_h($r['harvest_year'])?></b></td><td class="wrap"><b><?=ce_h($r['harvest_name'])?></b><?php if((string)$r['zone_name']!==''):?><br><small><?=ce_h($r['zone_name'])?></small><?php endif;?></td><td><span class="church-badge"><?=ce_h($r['harvest_category'])?></span></td><td><?=ce_h($r['audience'])?><?php if($r['department_names']!==''):?><br><small><?=ce_h($r['department_names'])?></small><?php endif;?></td><td class="record-progress"><small><span><?=number_format((float)$r['amount_collected'],0)?></span><span><?=number_format((float)$r['target_amount'],0)?></span></small><div class="church-progress" style="--progress:<?=round($pct,1)?>%"><span></span></div></td><td><span class="church-badge"><?=ce_h($r['status'])?></span></td><td><div class="church-table-actions"><button type="button" class="btn btn-info btn-sm js-action" data-action="view" data-record='<?=ce_h(json_encode($r,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG))?>'><i class="fas fa-eye"></i></button><button type="button" class="btn btn-primary btn-sm js-action" data-action="edit" data-record='<?=ce_h(json_encode($r,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG))?>'><i class="fas fa-edit"></i></button><button type="button" class="btn btn-danger btn-sm js-action" data-action="delete" data-id="<?=(int)$r['id']?>" data-name="<?=ce_h($r['harvest_name'])?>"><i class="fas fa-trash"></i></button></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="church-empty">No harvest records found.</td></tr><?php endif;?></tbody></table></div></div>
<div class="church-modal-backdrop" id="backdrop"></div>
<div class="church-modal" id="formModal"><div class="church-modal-dialog"><form method="post" action="../church_admin/process.php" id="recordForm"><?php ce_form_header('save_harvest','../harvests/');?><input type="hidden" name="id" id="recordId"><div class="church-modal-header"><h3 id="formTitle">Add Harvest</h3><button type="button" class="church-modal-close js-close">&times;</button></div><div class="church-modal-body"><div class="church-form"><div class="church-form-row"><label>Harvest Year<input type="number" name="harvest_year" id="harvest_year" min="2000" max="2100" required></label><label>Category<select name="harvest_category" id="harvest_category"><option value="Zone">Zone</option><option value="Sunday School">Sunday School</option><option value="General">General</option></select></label></div><label>Harvest Name<input name="harvest_name" id="harvest_name" maxlength="180" required></label><label id="zoneWrap">Church Zone <span class="req">*</span><select name="zone_id" id="zone_id"><option value="">Select church zone</option><?php foreach($zones as $zone):?><option value="<?=(int)$zone['id']?>"><?=ce_h($zone['name'])?><?php if(trim((string)($zone['zone_code']??''))!==''):?> (<?=ce_h($zone['zone_code'])?>)<?php endif;?></option><?php endforeach;?></select><?php if(!$zones):?><small class="text-danger">No church zones were found. Add zones before creating a Zone harvest.</small><?php endif;?></label><div class="church-form-row"><label>Target Amount<input type="number" step="0.01" min="0" name="target_amount" id="target_amount" value="0"></label><label>Amount Collected<input type="number" step="0.01" min="0" name="amount_collected" id="amount_collected" value="0"></label></div><div class="church-form-row"><label>Harvest Date<input type="date" name="harvest_date" id="harvest_date"></label><label>Status<select name="status" id="status"><option>Planning</option><option selected>Open</option><option>Completed</option><option>Cancelled</option></select></label></div><label>Notes<textarea name="notes" id="notes" rows="4"></textarea></label><label>Audience<select name="audience" id="audience"><option value="All Members">All Members</option><option value="Selected Departments">Selected Departments</option></select></label><div class="audience-departments" id="deptBox"><div class="department-actions"><button type="button" class="btn btn-sm btn-outline" id="selectAll">Select All</button><button type="button" class="btn btn-sm btn-outline" id="clearAll">Clear</button></div><div class="department-options"><?php foreach($departments as $d):?><label class="department-option"><input type="checkbox" name="department_ids[]" value="<?=(int)$d['id']?>"><span><?=ce_h($d['name'])?></span></label><?php endforeach;?><?php if(!$departments):?><div class="church-empty">No departments found.</div><?php endif;?></div></div></div></div><div class="church-modal-footer"><button type="button" class="btn btn-outline js-close">Cancel</button><button type="submit" class="btn btn-primary"><i class="fas fa-save"></i> Save Harvest</button></div></form></div></div>
