<div class="church-modal" id="deleteModal"><div class="church-modal-dialog church-modal-dialog-sm"><form method="post" action="../church_admin/process.php"><?php ce_form_header('delete_harvest','../harvests/');?><input type="hidden" name="id" id="deleteId"><div class="church-modal-header"><h3>Delete Harvest</h3><button type="button" class="church-modal-close js-close">&times;</button></div><div class="church-modal-body">Are you sure you want to delete <strong id="deleteName"></strong>?</div><div class="church-modal-footer"><button type="button" class="btn btn-outline js-close">Cancel</button><button type="submit" class="btn btn-danger"><i class="fas fa-trash"></i> Delete</button></div></form></div></div>
<script>
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
function openModal(id){$('#backdrop').classList.add('show');$(id).classList.add('show');document.body.classList.add('cms-modal-open')}
function closeModal(){$$('.church-modal,.church-modal-backdrop').forEach(x=>x.classList.remove('show'));document.body.classList.remove('cms-modal-open')}
$$('.js-close').forEach(x=>x.addEventListener('click',closeModal));$('#backdrop').addEventListener('click',closeModal);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function toggleDepartments(){$('#deptBox').classList.toggle('show',$('#audience').value==='Selected Departments')}
$('#audience').addEventListener('change',toggleDepartments);$('#selectAll').addEventListener('click',()=>$$('#deptBox input[type=checkbox]').forEach(x=>x.checked=true));$('#clearAll').addEventListener('click',()=>$$('#deptBox input[type=checkbox]').forEach(x=>x.checked=false));
function toggleZone(){
    const isZone=$('#harvest_category').value==='Zone';
    const wrap=$('#zoneWrap');
    const select=$('#zone_id');
    wrap.hidden=!isZone;
    select.required=isZone;
    select.disabled=!isZone;
    if(!isZone)select.value='';
}$('#harvest_category').addEventListener('change',toggleZone);
$('#addBtn').addEventListener('click',()=>{$('#recordForm').reset();$('#recordId').value='';$('#formTitle').textContent='Add Harvest';$$('#deptBox input[type=checkbox]').forEach(x=>x.checked=false);document.getElementById('harvest_year').value=new Date().getFullYear();document.getElementById('harvest_category').value='Zone';document.getElementById('target_amount').value='0';document.getElementById('amount_collected').value='0';document.getElementById('status').value='Open';toggleZone();toggleDepartments();openModal('#formModal')});
$$('.js-action').forEach(btn=>btn.addEventListener('click',()=>{if(btn.dataset.action==='delete'){$('#deleteId').value=btn.dataset.id||'';$('#deleteName').textContent=btn.dataset.name||'this record';openModal('#deleteModal');return}const r=JSON.parse(btn.dataset.record||'{}');if(btn.dataset.action==='view'){const fields={'Year':r.harvest_year,'Harvest':r.harvest_name,'Category':r.harvest_category,'Zone':r.zone_name,'Target Amount':Number(r.target_amount||0).toLocaleString(),'Amount Collected':Number(r.amount_collected||0).toLocaleString(),'Harvest Date':r.harvest_date,'Notes':r.notes,'Audience':r.audience+(r.department_names?' — '+r.department_names:''),'Status':r.status};$('#details').innerHTML=Object.entries(fields).map(([k,v])=>`<div class="modal-detail ${k==='Explanation'||k==='Notes'?'full':''}"><b>${k}</b><span>${String(v??'').trim()||'-'}</span></div>`).join('');openModal('#viewModal');return}$('#recordForm').reset();$('#recordId').value=r.id||'';$('#formTitle').textContent='Edit Harvest';['harvest_year','harvest_name','harvest_category','zone_id','target_amount','amount_collected','harvest_date','notes','audience','status'].forEach(k=>document.getElementById(k).value=r[k]??'');toggleZone();const ids=String(r.department_ids||'').split(',');$$('#deptBox input[type=checkbox]').forEach(x=>x.checked=ids.includes(x.value));toggleDepartments();openModal('#formModal')}));
$('#recordSearch').addEventListener('input',e=>{const q=e.target.value.toLowerCase().trim();$$('.church-table tbody tr[data-search]').forEach(row=>row.hidden=q!==''&&!row.dataset.search.includes(q))});
</script></div></div><?php require_once '../includes/footer.php';?>